<?php
declare(strict_types=1);
session_start(); require_once __DIR__.'/config.php'; $pdo=conectarBanco();
if (empty($_SESSION['usuario']) || $_SESSION['usuario']['perfil']!=='admin') { header('Location: login.php'); exit; }
$reunioes=$pdo->query("SELECT * FROM sprints WHERE modalidade_video='agendar' AND status_aprovacao NOT IN ('Publicado em Produção','Concluído') ORDER BY criado_em DESC")->fetchAll();
$concluidos=$pdo->query("SELECT * FROM sprints WHERE status_aprovacao IN ('Publicado em Produção','Concluído') ORDER BY criado_em DESC")->fetchAll();
$total=(int)$pdo->query('SELECT COUNT(*) FROM sprints')->fetchColumn();
function cartao(array $s): void { ?><article class="etapa-card"><div style="display:flex;justify-content:space-between;gap:1rem;flex-wrap:wrap"><strong><?=e($s['codigo'])?> · <?=e($s['cliente_nome'])?></strong><span class="tag-tech"><?=e($s['status_aprovacao'])?></span></div><p style="margin:.6rem 0"><?=e($s['receita_tipo'])?> — <?=e($s['descricao_ideia'])?></p><p><?=e($s['data_agendada']??'')?> <?=!empty($s['horario_agendado'])?'às '.e($s['horario_agendado']):''?> · <?=e($s['idioma'])?></p><p>Google Stitch: <?=e($s['stitch_status']??'Pendente')?> · Antigravity: <?=e($s['antigravity_status']??'Pendente')?></p><p><?php if(!empty($s['preview_url'])): ?><a href="<?=e($s['preview_url'])?>" target="_blank" rel="noopener">Abrir projeto</a><?php endif;?><?php if(!empty($s['stitch_preview_path'])):?> · <a href="<?=e($s['stitch_preview_path'])?>" target="_blank" rel="noopener">Ver tela do Stitch</a><?php endif;?><?php if(!empty($s['zoom_link'])):?> · <a href="<?=e($s['zoom_link'])?>" target="_blank" rel="noopener">Abrir reunião Zoom</a><?php endif;?></p></article><?php }
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Painel ADM — PurpleSprint</title><link rel="stylesheet" href="assets/style.css"></head><body><header class="header"><div class="logo-area"><a class="logo-home" href="index.php" aria-label="Voltar para a tela inicial"><span class="logo-icon">PurpleSprint ADM</span></a><span>Olá, <?=e($_SESSION['usuario']['nome'])?></span></div><nav><a class="tag-tech" href="index.php">Aplicação</a> <a class="tag-tech" href="logout.php">Sair</a></nav></header><main class="container"><section class="hero-topo"><h1>Painel administrativo</h1><p>Reuniões marcadas e projetos concluídos · <?=$total?> projetos registrados</p></section><section class="card"><h2 class="card-titulo">Reuniões agendadas (<?=count($reunioes)?>)</h2><?php if(!$reunioes):?><p>Nenhuma reunião agendada registrada.</p><?php else: foreach($reunioes as $s) cartao($s); endif;?></section><section class="card"><h2 class="card-titulo">Projetos concluídos / publicados (<?=count($concluidos)?>)</h2><?php if(!$concluidos):?><p>Ainda não há projetos publicados.</p><?php else: foreach($concluidos as $s) cartao($s); endif;?></section></main></body></html>
